import { createHash, randomBytes } from "node:crypto";

import { REPOSITORY } from "./taxonomy.mjs";

export const ASSISTANCE_DISCLOSURE =
  "> Generated by GitHub Copilot; AI-assisted and non-binding.";
export const CANVAS_CREATED_COMMENT_KIND = "aspnetcore-issue-triage-canvas-created";
export const MAX_PUBLICATION_BODY_BYTES = 64 * 1024;
export const MAX_PUBLICATION_CITATIONS = 64;
export const MAX_CITATION_URL_LENGTH = 2_048;
export const PUBLICATION_PREVIEW_TTL_MS = 10 * 60 * 1000;

const STOP_PATH_CLASSIFICATION = "Do not publish";
const STOP_PATH_MARKER = "Prohibited under the stop path";
const PUBLIC_GITHUB_REPOSITORY = "dotnet/aspnetcore";
const PUBLIC_CITATION_HOSTS = new Set([
  "api.github.com",
  "api.nuget.org",
  "dotnet.microsoft.com",
  "learn.microsoft.com",
  "nuget.org",
  "raw.githubusercontent.com",
]);
const FORBIDDEN_MARKERS = [
  /\bconfidential\b/i,
  /\binternal[- ]only\b/i,
  /\blocal[- ]diagnostic(?:s)?\b/i,
  /\bdiagnostic[- ](?:capture|artifact|setting|output)\b/i,
  /diagnostic-settings\.json/i,
  /ASPNETCORE_ISSUE_TRIAGE_MODEL/i,
];

export function hashPublicationBody(body) {
  validatePublicationBody(body);
  return createHash("sha256").update(body, "utf8").digest("hex");
}

export function getIssueRevision(issue) {
  const revision = issue?.revision ?? issue?.updatedAt ?? issue?.etag;
  if (typeof revision !== "string" || !revision) {
    throw publicationError("issue_revision_missing", "The public issue has no usable revision.");
  }
  return revision;
}

export function validatePublicIssue(issue, expectedNumber = issue?.number) {
  if (
    !issue
    || issue.repository !== REPOSITORY
    || !Number.isSafeInteger(issue.number)
    || issue.number < 1
    || issue.number !== expectedNumber
    || issue.url !== `https://github.com/${REPOSITORY}/issues/${issue.number}`
    || issue.state !== "open"
    || issue.public !== true
    || issue.isPullRequest !== false
  ) {
    throw publicationError(
      "canonical_issue_invalid",
      "Publication requires the expected public dotnet/aspnetcore issue.",
    );
  }
  return issue;
}

export function validateHumanAccount(account) {
  if (
    !account
    || typeof account.login !== "string"
    || !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(account.login)
    || !Number.isSafeInteger(account.id)
    || account.id < 1
    || account.isBot === true
    || account.type === "Bot"
    || account.userType === "Bot"
    || /\[bot\]$/i.test(account.login)
  ) {
    throw publicationError(
      "human_account_required",
      "Publication requires an authenticated human GitHub account.",
    );
  }
  return account;
}

export function validatePublicationBody(body, { report = null } = {}) {
  if (typeof body !== "string" || !body.trim()) {
    throw publicationError("publication_body_invalid", "Publication body must be nonempty Markdown.");
  }
  if (Buffer.byteLength(body, "utf8") > MAX_PUBLICATION_BODY_BYTES) {
    throw publicationError(
      "publication_body_too_large",
      `Publication body must not exceed ${MAX_PUBLICATION_BODY_BYTES} bytes.`,
    );
  }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(body)) {
    throw publicationError("publication_body_invalid", "Publication body contains control characters.");
  }
  if ((body.split(ASSISTANCE_DISCLOSURE).length - 1) !== 1) {
    throw publicationError(
      "publication_disclosure_missing",
      "Publication body must retain exactly one assistance disclosure.",
    );
  }
  const forbidden = FORBIDDEN_MARKERS.find((marker) => marker.test(body));
  if (forbidden) {
    throw publicationError(
      "publication_confidential_marker",
      "Publication body contains a confidential or local-diagnostic marker.",
    );
  }
  validatePublicationCitations(body);
  const classification = readClassification(body);
  const recordedClassification = report?.classification;
  if (
    recordedClassification !== undefined
    && (!isPublicationClassification(recordedClassification)
      || recordedClassification !== classification)
  ) {
    throw publicationError(
      "publication_classification_mismatch",
      "The approved publication classification does not match the report.",
    );
  }
  if (report?.stopPath === true || recordedClassification === STOP_PATH_CLASSIFICATION) {
    throw publicationError(
      "publication_stop_path",
      "A report on the unresolved stop path cannot be published.",
    );
  }
  if (
    classification === STOP_PATH_CLASSIFICATION
    || body.includes(STOP_PATH_MARKER)
    || isStopPathAssessment(body)
  ) {
    throw publicationError(
      "publication_stop_path",
      "A report on the unresolved stop path cannot be published.",
    );
  }
  return body;
}

export function validatePublicationCitations(markdown) {
  if (typeof markdown !== "string") {
    throw publicationError("publication_citation_invalid", "Citation input must be Markdown.");
  }
  const urls = extractCitationUrls(markdown);
  if (urls.length > MAX_PUBLICATION_CITATIONS) {
    throw publicationError(
      "publication_citations_too_many",
      `Publication may contain at most ${MAX_PUBLICATION_CITATIONS} citations.`,
    );
  }
  for (const value of urls) {
    if (value.length > MAX_CITATION_URL_LENGTH) {
      throw publicationError(
        "publication_citation_invalid",
        "A publication citation URL is too long.",
      );
    }
    let url;
    try {
      url = new URL(value);
    } catch {
      throw publicationError("publication_citation_invalid", "Publication contains an invalid citation URL.");
    }
    if (
      url.protocol !== "https:"
      || url.username
      || url.password
      || url.port
      || !isAllowedPublicCitation(url)
    ) {
      throw publicationError(
        "publication_citation_invalid",
        "Publication citations must target bounded public evidence URLs.",
      );
    }
  }
  return urls;
}

export function createPublicationPreview(options = {}) {
  if (Object.hasOwn(options, "commentId")) {
    throw publicationError(
      "recorded_comment_invalid",
      "Comment IDs must come from a recorded canvas-created comment.",
    );
  }
  const {
    issue,
    account,
    report = null,
    draftRevision = null,
    approvedBody,
    recordedComment = null,
    createConfirmationToken = defaultConfirmationToken,
  } = options;
  validatePublicIssue(issue);
  validateHumanAccount(account);
  if (report !== null && (!report || typeof report !== "object" || Array.isArray(report))) {
    throw publicationError("publication_report_invalid", "The stored report is invalid.");
  }
  if (report?.repository !== undefined && report.repository !== REPOSITORY) {
    throw publicationError("publication_report_invalid", "The report belongs to another repository.");
  }
  if (report?.issueNumber !== undefined && report.issueNumber !== issue.number) {
    throw publicationError("publication_report_invalid", "The report belongs to another issue.");
  }
  const reportBody = report?.content;
  if (approvedBody !== undefined && reportBody !== undefined && approvedBody !== reportBody) {
    throw publicationError("publication_body_mismatch", "The approved body must be exact report content.");
  }
  const body = reportBody ?? approvedBody;
  validatePublicationBody(body, { report });
  const issueRevision = getIssueRevision(issue);
  if (!Number.isSafeInteger(draftRevision) || draftRevision < 1) {
    throw publicationError("publication_revision_invalid", "A current draft revision is required.");
  }
  const normalizedRecordedComment = recordedComment === null
    ? null
    : validateRecordedComment(recordedComment, {
      issue,
      account,
      bodyHash: recordedComment.bodyHash,
    });
  const token = createConfirmationToken();
  if (typeof token !== "string" || token.length < 16 || token.length > 256) {
    throw publicationError("confirmation_token_invalid", "A usable confirmation token is required.");
  }
  return {
    schemaVersion: "1.0.0",
    repository: REPOSITORY,
    issueNumber: issue.number,
    issueUrl: issue.url,
    issueRevision,
    draftRevision,
    accountLogin: account.login,
    accountId: account.id,
    body,
    bodyHash: hashPublicationBody(body),
    operation: normalizedRecordedComment ? "update" : "create",
    recordedComment: normalizedRecordedComment,
    confirmationToken: token,
    expiresAt: new Date(Date.now() + PUBLICATION_PREVIEW_TTL_MS).toISOString(),
  };
}

export function confirmPublicationPreview(
  preview,
  confirmationToken,
  { issue, account, comment = null } = {},
) {
  validatePreview(preview);
  if (confirmationToken !== preview.confirmationToken) {
    throw publicationError(
      "confirmation_required",
      "The preview confirmation token is missing or stale.",
    );
  }
  validatePublicIssue(issue, preview.issueNumber);
  validateHumanAccount(account);
  if (account.login !== preview.accountLogin || account.id !== preview.accountId) {
    throw publicationError("account_changed", "The authenticated GitHub account changed.");
  }
  if (getIssueRevision(issue) !== preview.issueRevision) {
    throw publicationError("stale_issue_revision", "The issue changed after preview confirmation.");
  }
  if (hashPublicationBody(preview.body) !== preview.bodyHash) {
    throw publicationError("publication_hash_mismatch", "The approved body hash is stale.");
  }
  if (preview.operation === "update") {
    validateLiveRecordedComment(comment, preview);
  } else if (comment !== null) {
    throw publicationError("publication_comment_conflict", "A create preview cannot use a comment.");
  }
  return true;
}

export function createPublicationService(adapter, {
  createAttemptId = defaultAttemptId,
  recordAttempt = adapter?.recordAttempt,
  initialAttempts = [],
} = {}) {
  requireAdapter(adapter);
  if (recordAttempt !== undefined && typeof recordAttempt !== "function") {
    throw publicationError("publication_attempt_hook_invalid", "The attempt hook must be a function.");
  }
  if (!Array.isArray(initialAttempts)) {
    throw publicationError("publication_attempts_invalid", "Initial publication attempts must be an array.");
  }
  const issueTails = new Map();
  const pending = new Map();
  const completed = new Map();
  const createdByIssue = new Map();

  async function publish(preview, confirmationToken) {
    validatePreview(preview);
    const issueKey = `${REPOSITORY}#${preview.issueNumber}`;
    return enqueue(issueTails, issueKey, async () => {
      const completedKey = publicationKey(preview);
      if (completed.has(completedKey)) {
        return completed.get(completedKey);
      }
      if (pending.has(issueKey)) {
        throw publicationError(
          "publication_pending",
          "A publication attempt has an unknown outcome; resolve it before trying again.",
        );
      }
      if (preview.operation === "create" && createdByIssue.has(issueKey)) {
        throw publicationError(
          "publication_exists",
          "This issue already has a recorded canvas-created publication.",
        );
      }

      const issue = validatePublicIssue(
        await adapter.readIssue(preview.issueNumber),
        preview.issueNumber,
      );
      const account = validateHumanAccount(await adapter.readAccount());
      const comment = preview.operation === "update"
        ? await readRecordedComment(adapter, preview)
        : null;
      confirmPublicationPreview(preview, confirmationToken, { issue, account, comment });

      const attempt = {
        attemptId: createAttemptId(),
        preview,
        operation: preview.operation,
        attemptedAt: new Date(Math.floor(Date.now() / 1_000) * 1_000).toISOString(),
      };
      pending.set(issueKey, attempt);
      try {
        await recordAttempt?.(attemptRecord(attempt, "pending"));
      } catch (error) {
        pending.delete(issueKey);
        throw publicationError(
          "publication_attempt_persist_failed",
          `The publication attempt could not be recorded: ${error.message}`,
        );
      }
      try {
        const response = preview.operation === "create"
          ? await adapter.createComment({
            repository: REPOSITORY,
            issueNumber: preview.issueNumber,
            body: preview.body,
          })
          : await adapter.updateComment({
            repository: REPOSITORY,
            issueNumber: preview.issueNumber,
            commentId: preview.recordedComment.id,
            body: preview.body,
          });
        if (isUnknownOutcome(response)) {
          const persistenceWarning = await recordAttemptSafely(recordAttempt, attempt, "unknown");
          return unknownOutcome(issueKey, attempt, persistenceWarning);
        }
        const recorded = createRecordedComment(
          response,
          preview,
          account,
          issue,
        );
        const result = {
          status: "published",
          operation: preview.operation,
          issueNumber: preview.issueNumber,
          body: preview.body,
          bodyHash: preview.bodyHash,
          recordedComment: recorded,
        };
        pending.delete(issueKey);
        completed.set(completedKey, result);
        createdByIssue.set(issueKey, result);
        const persistenceWarning = await recordAttemptSafely(
          recordAttempt,
          attempt,
          "published",
          result.recordedComment,
        );
        if (persistenceWarning) {
          pending.set(issueKey, attempt);
          result.persistenceWarning = persistenceWarning;
          result.pendingIssueKey = issueKey;
        }
        return result;
      } catch (error) {
        if (isAmbiguousError(error)) {
          const persistenceWarning = await recordAttemptSafely(recordAttempt, attempt, "unknown");
          return unknownOutcome(issueKey, attempt, persistenceWarning);
        }
        pending.delete(issueKey);
        throw error;
      }
    });
  }

  async function resolvePending(preview) {
    validatePreview(preview, { allowExpired: true });
    const issueKey = `${REPOSITORY}#${preview.issueNumber}`;
    return enqueue(issueTails, issueKey, async () => {
      const attempt = pending.get(issueKey);
      if (!attempt) {
        throw publicationError("publication_not_pending", "No pending publication attempt exists.");
      }
      if (attempt.preview.bodyHash !== preview.bodyHash || attempt.operation !== preview.operation) {
        throw publicationError("publication_pending", "Only the pending publication can be resolved.");
      }
      if (publicationKey(attempt.preview) !== publicationKey(preview)
        || attempt.preview.confirmationToken !== preview.confirmationToken) {
        throw publicationError("publication_pending", "Only the pending publication can be resolved.");
      }
      const issue = validatePublicIssue(
        await adapter.readIssue(preview.issueNumber),
        preview.issueNumber,
      );
      const account = validateHumanAccount(await adapter.readAccount());
      const comment = await adapter.readComment(readCommentQuery(preview, attempt.attemptedAt));
      if (comment === null || comment?.deleted === true) {
        return unknownOutcome(issueKey, attempt);
      }
      validatePendingResolution(preview, issue, account, comment);
      const recorded = createRecordedComment(comment, preview, account, issue);
      const result = {
        status: "published",
        recovered: true,
        operation: preview.operation,
        issueNumber: preview.issueNumber,
        body: preview.body,
        bodyHash: preview.bodyHash,
        recordedComment: recorded,
      };
      pending.delete(issueKey);
      completed.set(publicationKey(preview), result);
      createdByIssue.set(issueKey, result);
      const persistenceWarning = await recordAttemptSafely(
        recordAttempt,
        attempt,
        "published",
        result.recordedComment,
      );
      if (persistenceWarning) {
        pending.set(issueKey, attempt);
        result.persistenceWarning = persistenceWarning;
        result.pendingIssueKey = issueKey;
      }
      return result;
    });
  }

  function restorePendingAttempt(record) {
    const attempt = validatePendingAttempt(record);
    const issueKey = `${REPOSITORY}#${attempt.preview.issueNumber}`;
    if (pending.has(issueKey)) {
      throw publicationError(
        "publication_pending",
        "A publication attempt for this issue is already pending.",
      );
    }
    pending.set(issueKey, attempt);
    return attempt;
  }

  for (const record of initialAttempts) {
    restorePendingAttempt(record);
  }

  return {
    getPendingAttempt: (issueNumber) => pending.get(`${REPOSITORY}#${issueNumber}`) ?? null,
    publish,
    resolvePending,
    restorePendingAttempt,
  };
}

export function validatePendingAttempt(record) {
  if (
    !record
    || typeof record.attemptId !== "string"
    || !record.attemptId
    || !["pending", "unknown"].includes(record.status)
    || record.repository !== REPOSITORY
    || !record.preview
  ) {
    throw publicationError("publication_attempt_invalid", "The durable publication attempt is invalid.");
  }
  validatePreview(record.preview, { allowExpired: true });
  if (
    record.operation !== record.preview.operation
    || record.issueNumber !== record.preview.issueNumber
    || record.accountLogin !== record.preview.accountLogin
    || record.accountId !== record.preview.accountId
    || record.bodyHash !== record.preview.bodyHash
    || record.body !== record.preview.body
  ) {
    throw publicationError("publication_attempt_invalid", "The durable publication attempt does not match its preview.");
  }
  return {
    attemptId: record.attemptId,
    attemptedAt: record.attemptedAt,
    preview: record.preview,
    operation: record.operation,
  };
}

export function validateRecordedComment(recordedComment, { issue, account, bodyHash } = {}) {
  const htmlUrl = recordedComment?.html_url ?? recordedComment?.htmlUrl;
  if (
    !recordedComment
    || recordedComment.kind !== CANVAS_CREATED_COMMENT_KIND
    || !isCommentId(recordedComment.id)
    || recordedComment.repository !== REPOSITORY
    || recordedComment.issueNumber !== issue?.number
    || recordedComment.accountLogin !== account?.login
    || recordedComment.accountId !== account?.id
    || recordedComment.authorId !== account?.id
    || typeof recordedComment.bodyHash !== "string"
    || !/^[a-f0-9]{64}$/.test(recordedComment.bodyHash)
    || typeof recordedComment.body !== "string"
    || typeof htmlUrl !== "string"
    || htmlUrl !== canonicalCommentUrl(recordedComment.issueNumber, recordedComment.id)
    || typeof (recordedComment.issueRevision ?? recordedComment.revision) !== "string"
    || !(recordedComment.issueRevision ?? recordedComment.revision)
  ) {
    throw publicationError(
      "recorded_comment_invalid",
      "Only a recorded canvas-created comment may be updated.",
    );
  }
  if (bodyHash !== undefined && recordedComment.bodyHash !== bodyHash) {
    throw publicationError("recorded_comment_invalid", "The recorded comment body binding is invalid.");
  }
  if (hashPublicationBody(recordedComment.body) !== recordedComment.bodyHash) {
    throw publicationError("recorded_comment_invalid", "The recorded comment body binding is invalid.");
  }
  return recordedComment;
}

function validatePreview(preview, { allowExpired = false } = {}) {
  if (
    !preview
    || preview.schemaVersion !== "1.0.0"
    || preview.repository !== REPOSITORY
    || !Number.isSafeInteger(preview.issueNumber)
    || typeof preview.issueUrl !== "string"
    || typeof preview.issueRevision !== "string"
    || !Number.isSafeInteger(preview.draftRevision)
    || preview.draftRevision < 1
    || typeof preview.accountLogin !== "string"
    || !Number.isSafeInteger(preview.accountId)
    || preview.accountId < 1
    || typeof preview.body !== "string"
    || typeof preview.bodyHash !== "string"
    || !["create", "update"].includes(preview.operation)
    || typeof preview.confirmationToken !== "string"
  ) {
    throw publicationError("publication_preview_invalid", "The publication preview is invalid.");
  }
  if (typeof preview.expiresAt !== "string" || !Number.isFinite(Date.parse(preview.expiresAt))) {
    throw publicationError("publication_preview_invalid", "The publication preview expiration is invalid.");
  }
  if (!allowExpired && Date.parse(preview.expiresAt) <= Date.now()) {
    throw publicationError("confirmation_expired", "The publication preview has expired.");
  }
  validatePublicIssue({
    repository: preview.repository,
    number: preview.issueNumber,
    url: preview.issueUrl,
    state: "open",
    public: true,
    isPullRequest: false,
    updatedAt: preview.issueRevision,
  });
  validatePublicationBody(preview.body);
  if (hashPublicationBody(preview.body) !== preview.bodyHash) {
    throw publicationError("publication_hash_mismatch", "The approved body hash is stale.");
  }
  if (preview.operation === "create" && preview.recordedComment !== null) {
    throw publicationError("publication_preview_invalid", "Create previews cannot contain a comment binding.");
  }
  if (preview.operation === "update") {
    validateRecordedComment(preview.recordedComment, {
      issue: { number: preview.issueNumber },
      account: { login: preview.accountLogin, id: preview.accountId },
    });
  }
}

function readClassification(body) {
  const match = /^\*\*Classification:\*\*[ \t]*([^\r\n]+?)[ \t]*$/m.exec(body);
  if (!match || !isPublicationClassification(match[1].trim())) {
    throw publicationError("publication_classification_invalid", "The report classification is invalid.");
  }
  return match[1].trim();
}

function isPublicationClassification(value) {
  return ["Research", "Investigation plan", "Implementation-ready handoff"].includes(value)
    || value === STOP_PATH_CLASSIFICATION;
}

function isStopPathAssessment(body) {
  return /^\*\*Preliminary assessment:\*\*[ \t]*(?:Insufficient evidence|Security process required)[ \t]*$/m.test(body)
    && body.includes(STOP_PATH_MARKER);
}

function validateLiveRecordedComment(comment, preview) {
  if (!comment || comment.deleted === true) {
    throw publicationError("recorded_comment_deleted", "The recorded canvas-created comment was deleted.");
  }
  if (
    comment.repository !== REPOSITORY
    || comment.issueNumber !== preview.issueNumber
    || !isCommentId(comment.id)
    || String(comment.id) !== String(preview.recordedComment.id)
    || comment.html_url !== canonicalCommentUrl(preview.issueNumber, comment.id)
  ) {
    throw publicationError("recorded_comment_stale", "The recorded comment identity is stale.");
  }
  const author = comment.author ?? comment.user?.login;
  const authorId = getCommentAuthorId(comment);
  if (author !== preview.accountLogin || authorId !== preview.accountId) {
    throw publicationError("external_comment", "The recorded comment is owned by another account.");
  }
  if (
    typeof comment.body !== "string"
    || hashPublicationBody(comment.body) !== preview.recordedComment.bodyHash
  ) {
    throw publicationError("recorded_comment_stale", "The recorded comment body was changed.");
  }
  return comment;
}

function readCommentQuery(preview, attemptedAt = preview.attemptedAt) {
  return preview.operation === "update"
    ? {
      repository: REPOSITORY,
      issueNumber: preview.issueNumber,
      id: preview.recordedComment.id,
    }
    : {
      repository: REPOSITORY,
      issueNumber: preview.issueNumber,
      bodyHash: preview.bodyHash,
      accountId: preview.accountId,
      attemptedAt,
    };
}

async function readRecordedComment(adapter, preview) {
  return adapter.readComment(readCommentQuery(preview));
}

function validateRecoveredCreateComment(comment, preview, account) {
  if (!comment || comment.deleted === true) {
    throw publicationError("recorded_comment_deleted", "The observed pending comment was deleted.");
  }
  const author = comment.author ?? comment.user?.login;
  const authorId = getCommentAuthorId(comment);
  if (
    comment.repository !== REPOSITORY
    || comment.issueNumber !== preview.issueNumber
    || !isCommentId(comment.id)
    || author !== account.login
    || authorId !== account.id
    || comment.html_url !== canonicalCommentUrl(preview.issueNumber, comment.id)
    || typeof comment.body !== "string"
    || hashPublicationBody(comment.body) !== preview.bodyHash
  ) {
    throw publicationError("external_comment", "The observed comment does not match the pending publication.");
  }
  return comment;
}

function validatePendingResolution(preview, issue, account, comment) {
  validatePublicIssue(issue, preview.issueNumber);
  validateHumanAccount(account);
  if (account.login !== preview.accountLogin || account.id !== preview.accountId) {
    throw publicationError("account_changed", "The authenticated GitHub account changed.");
  }
  if (hashPublicationBody(preview.body) !== preview.bodyHash) {
    throw publicationError("publication_hash_mismatch", "The approved body hash is stale.");
  }
  if (preview.operation === "create") {
    validateRecoveredCreateComment(comment, preview, account);
  } else {
    validatePendingUpdateComment(comment, preview);
  }
}

function validatePendingUpdateComment(comment, preview) {
  const author = comment?.author ?? comment?.user?.login;
  const authorId = getCommentAuthorId(comment);
  if (
    !comment
    || comment.deleted === true
    || comment.repository !== REPOSITORY
    || comment.issueNumber !== preview.issueNumber
    || !isCommentId(comment.id)
    || String(comment.id) !== String(preview.recordedComment.id)
    || comment.html_url !== canonicalCommentUrl(preview.issueNumber, comment.id)
    || author !== preview.accountLogin
    || authorId !== preview.accountId
    || typeof comment.body !== "string"
    || comment.body !== preview.body
    || hashPublicationBody(comment.body) !== preview.bodyHash
  ) {
    throw publicationError(
      "recorded_comment_stale",
      "The pending update did not produce the approved comment body.",
    );
  }
  return comment;
}

function createRecordedComment(comment, preview, account, issue) {
  if (
    !comment
    || !isCommentId(comment.id)
    || comment.repository !== REPOSITORY
    || comment.issueNumber !== preview.issueNumber
    || comment.html_url !== canonicalCommentUrl(preview.issueNumber, comment.id)
    || typeof comment.body !== "string"
    || comment.body !== preview.body
    || (comment.author ?? comment.user?.login) !== account.login
    || getCommentAuthorId(comment) !== account.id
  ) {
    throw publicationError(
      "publication_response_invalid",
      "GitHub returned an unusable comment receipt.",
      { ambiguous: true },
    );
  }
  return {
    kind: CANVAS_CREATED_COMMENT_KIND,
    id: comment.id,
    repository: REPOSITORY,
    issueNumber: preview.issueNumber,
    accountLogin: account.login,
    accountId: account.id,
    authorId: getCommentAuthorId(comment),
    bodyHash: preview.bodyHash,
    body: comment.body,
    html_url: comment.html_url,
    htmlUrl: comment.html_url,
    issueRevision: getIssueRevision(issue),
    revision: getIssueRevision(issue),
    commentRevision: comment.updatedAt ?? comment.revision ?? null,
  };
}

function getCommentAuthorId(comment) {
  return comment.authorId ?? comment.user?.id;
}

function canonicalCommentUrl(issueNumber, commentId) {
  return `https://github.com/${REPOSITORY}/issues/${issueNumber}#issuecomment-${commentId}`;
}

function extractCitationUrls(markdown) {
  const urls = [];
  const seen = new Set();
  const add = (value) => {
    const normalized = value.replace(/[.,;:!?]+$/, "");
    if (!seen.has(normalized)) {
      seen.add(normalized);
      urls.push(normalized);
    }
  };

  for (const match of markdown.matchAll(/\]\(\s*([^\s)]+)\s*\)/g)) {
    add(match[1]);
  }
  for (const match of markdown.matchAll(
    /(?:https?|file|ftp):\/\/[^\s<>)\]]+/gi,
  )) {
    add(match[0]);
  }
  return urls;
}

function isAllowedPublicCitation(url) {
  if (url.hostname === "github.com") {
    return isAllowedAspnetCoreGithubUrl(url);
  }
  if (url.hostname === "api.github.com") {
    return /^\/repos\/dotnet\/aspnetcore(?:\/|$)/.test(url.pathname);
  }
  if (url.hostname === "raw.githubusercontent.com") {
    return /^\/dotnet\/aspnetcore\/[^/]+(?:\/|$)/.test(url.pathname);
  }
  return PUBLIC_CITATION_HOSTS.has(url.hostname);
}

function isAllowedAspnetCoreGithubUrl(url) {
  const segments = url.pathname.split("/").filter(Boolean);
  if (segments.length < 2 || `${segments[0]}/${segments[1]}` !== PUBLIC_GITHUB_REPOSITORY) {
    return false;
  }
  if (segments.length === 2) {
    return true;
  }
  const kind = segments[2];
  if (["issues", "pull", "discussions"].includes(kind)) {
    return segments.length === 4 && /^[1-9][0-9]*$/.test(segments[3]);
  }
  if (kind === "commit") {
    return segments.length === 4 && /^[a-f0-9]{7,64}$/i.test(segments[3]);
  }
  if (kind === "blob" || kind === "tree") {
    return segments.length >= 5 && !segments[3].includes("..");
  }
  return false;
}

function publicationKey(preview) {
  return `${REPOSITORY}#${preview.issueNumber}:${preview.accountLogin}:${preview.issueRevision}:${preview.bodyHash}:${preview.operation}`;
}

function unknownOutcome(issueKey, attempt, persistenceWarning = null) {
  return {
    status: "unknown",
    retryAllowed: false,
    issueNumber: attempt.preview.issueNumber,
    operation: attempt.operation,
    attemptId: attempt.attemptId,
    message: "The write outcome is unknown. Resolve the pending attempt by reading GitHub; do not retry.",
    pendingIssueKey: issueKey,
    ...(persistenceWarning ? { persistenceWarning } : {}),
  };
}

function attemptRecord(attempt, status, recordedComment = null) {
  return {
    attemptId: attempt.attemptId,
    attemptedAt: attempt.attemptedAt,
    repository: REPOSITORY,
    issueNumber: attempt.preview.issueNumber,
    operation: attempt.operation,
    issueRevision: attempt.preview.issueRevision,
    accountLogin: attempt.preview.accountLogin,
    accountId: attempt.preview.accountId,
    bodyHash: attempt.preview.bodyHash,
    body: attempt.preview.body,
    preview: attempt.preview,
    recordedComment,
    status,
  };
}

async function recordAttemptSafely(recordAttempt, attempt, status, recordedComment = null) {
  try {
    await recordAttempt?.(attemptRecord(attempt, status, recordedComment));
    return null;
  } catch (error) {
    return {
      code: "publication_attempt_persist_failed",
      message: `The remote publication outcome is known, but the local receipt could not be saved: ${error.message}`,
    };
  }
}

function enqueue(tails, key, operation) {
  const previous = tails.get(key) ?? Promise.resolve();
  const result = previous.catch(() => {}).then(operation);
  const tail = result.then(() => undefined, () => undefined);
  tails.set(key, tail);
  void tail.finally(() => {
    if (tails.get(key) === tail) {
      tails.delete(key);
    }
  });
  return result;
}

function requireAdapter(adapter) {
  const methods = ["readIssue", "readAccount", "readComment", "createComment", "updateComment"];
  if (!adapter || methods.some((method) => typeof adapter[method] !== "function")) {
    throw publicationError("publication_adapter_invalid", "The publication adapter is incomplete.");
  }
}

function isCommentId(value) {
  return (Number.isSafeInteger(value) && value > 0)
    || (typeof value === "string" && /^[1-9][0-9]{0,19}$/.test(value));
}

function isUnknownOutcome(value) {
  return value?.status === "unknown" || value?.outcome === "unknown" || value?.unknown === true;
}

function isAmbiguousError(error) {
  return error?.ambiguous === true
    || error?.unknownOutcome === true
    || ["ambiguous", "network", "timeout", "unknown_outcome"].includes(error?.code);
}

function defaultAttemptId() {
  return randomBytes(16).toString("hex");
}

function defaultConfirmationToken() {
  return randomBytes(24).toString("base64url");
}

function publicationError(code, message, details = {}) {
  const error = new Error(message);
  error.code = code;
  Object.assign(error, details);
  return error;
}
